import {themes,dictionaries} from './data.js';
export const defaults=Object.freeze([25,30,15,20,10]);
export const dimensionNames=['馆藏主题契合度','参观意图强度','时间地点适配度','体验需求匹配度','信号质量与时效性'];
export function hasTerm(text,term){return /^[a-z ]+$/i.test(term)?new RegExp('\\b'+term+'\\b','i').test(text):text.includes(term);}
const alias={孩子:['child','children','kids'],亲子:['family'],手作:['workshop','hands-on'],动手:['interactive','hands-on'],拍照:['photography','photo','photos'],历史:['history','historical'],文物:['artifacts','artefacts'],文化:['culture','cultural'],青铜:['bronze'],铸造:['casting','foundry'],工艺:['craft','crafts'],周末:['weekend'],知识:['learning','educational'],休闲:['relax'],排队:['queue','queues','crowded']};
export function analyze(post,resources,weights=defaults){
 const t=post.text||'', hits=dictionaries.map(d=>d.filter(k=>hasTerm(t,k))), counts=hits.map(h=>h.length);let index=counts.indexOf(Math.max(...counts));if(!Math.max(...counts))index=-1;
 let intent=post.kind==='visitor-review'?(/来过|去过|参观过|我们去|去的时候|去了|参观了|来了两次|带孩子去的|今天去了/.test(t)?'已经参观':'历史评论/到访待核实'):/不想|不考虑|不去了|不再|\b(don't want|do not want|never again)\b/i.test(t)?'负面/排斥':/已经|去过|上次|参加过|参观过|\b(visited|went to|have been to|last visit)\b/i.test(t)?'已经参观':/计划|准备|预约.*课|\b(plan to visit|planning to visit|booked tickets)\b/i.test(t)?'明确参观计划':/想|希望|最好|能.*体验|有什么|哪里|\b(want to|would like|looking for|any recommendations)\b/i.test(t)?'潜在体验需求':index>=0?'一般兴趣':'无关内容';
 const matches=resources.map(r=>({...r,hits:r.keywords.split(/[、,，\s]+/).filter(k=>k&&(hasTerm(t,k)||(alias[k]||[]).some(a=>hasTerm(t,a))))})).filter(r=>r.hits.length).sort((a,b)=>b.hits.length-a.hits.length).slice(0,3);
 const historic=post.kind==='visitor-review',time=!historic&&/周末|下周|这周|周一|\b(this weekend|next week|tomorrow)\b/i.test(t),experience=/动手|制作|体验|手作|拍照|照片|拍摄|摄影|研学|散步|学习|知识|互动|\b(workshop|hands-on|interactive|photography|learning|educational)\b/i.test(t);
 const dateOK=post.date&&Number.isFinite(Date.parse(post.date)),age=dateOK?Math.floor((Date.now()-Date.parse(post.date))/86400000):null,stale=age!==null&&age>365;
 const values=[index<0?0:matches.length?Math.min(98,58+matches[0].hits.length*10):25,({'负面/排斥':8,'已经参观':12,'历史评论/到访待核实':12,'明确参观计划':92,'潜在体验需求':70,'一般兴趣':32,'无关内容':0})[intent],time?55:null,experience?(matches.length?88:35):null,dateOK?Math.max(5,100-Math.max(0,age)*.3):null];
 const known=values.reduce((s,v,i)=>s+(v===null?0:weights[i]),0),total=weights.reduce((a,b)=>a+b,0),score=known?Math.round(values.reduce((s,v,i)=>s+(v??0)*weights[i],0)/known):null,coverage=total?Math.round(known/total*100):0;
 const uncertainties=['未确认真实位置、年龄、未来到访日期及预约条件','资源匹配是对示例馆的跨馆启发，不表示评论指向该馆'];if(historic)uncertainties.push('历史到访评价只作为体验反馈，不能计入新观众高潜力名单');if(historic&&/军事博物馆/.test(t)&&!post.museumName?.includes('军事'))uncertainties.push('正文提到军事博物馆，与研究附件的所属馆标注可能冲突，需核对原文');if(stale)uncertainties.push('原评超过一年，不用于判断当前到访需求或当前开放规则');if(!post.sourceUrl)uncertainties.push('缺少原始来源链接，来源真实性待核实');if(/拍照|照片|拍摄|汉服|摄影|\b(photo|photography)\b/i.test(t))uncertainties.push('拍摄需求不代表允许商业摄影；须核实馆方限制');if(!time)uncertainties.push('没有可用于未来到访的时间适配证据');
 return {post,theme:index<0?'其他':themes[index],intent,hits:[...new Set(hits.flat())],matches,values,score,coverage,stale,high:score>=70&&coverage>=70&&['明确参观计划','潜在体验需求'].includes(intent)&&!!matches.length&&post.kind==='public-discussion'&&!!post.sourceUrl&&age!==null&&age>=0&&age<=365&&post.review!=='rejected',uncertainties,reasons:[matches.length?'词项匹配：'+matches[0].hits.join('、')+'；非 Embedding 相似度':'未找到馆藏词项匹配',historic?'历史评论来源不保证实际入馆；只按原文明确线索标注到访，不因“推荐、值得”提升未来意向':'按原文否定、历史、计划和需求表达分类；需人工复核',time?'只有未来时间线索，位置仍未知':'历史评论或时间地点证据不足，不计入分母',experience?'检测到体验或学习表达；历史体验不等于未来需求':'没有明确体验表达',dateOK?'按实际运行日期计算原评距今天数；采集时间不替代发布时间；旧评论时效低分':'原始发布时间未知，证据不足']};
}
export function aggregate(results){return themes.map(theme=>{const rows=results.filter(r=>r.theme===theme),n=rows.length,avg=k=>n?rows.reduce((s,r)=>s+(k(r)||0),0)/n:0;const strength=avg(r=>r.score),fit=avg(r=>r.values[0]),coverage=avg(r=>r.coverage),difficulty=theme==='摄影与空间体验'?55:80,history=rows.filter(r=>r.post.kind==='visitor-review').length;return {theme,rows,n,history,strength:Math.round(strength),explicit:n?Math.round(rows.filter(r=>r.intent==='明确参观计划').length/n*100):0,fit:Math.round(fit),coverage:Math.round(coverage),difficulty,index:Math.round(Math.min(n/30,1)*20+strength*.25+fit*.25+coverage*.2+difficulty*.1)};}).filter(g=>g.n);}
export const analysisProvider={mode:'local-rules',analyze};
